def _reset_logging(cls):
    """
    Reset the root logger to its default state. This removes all handlers,
    reverts to the default log level (WARNING) and clears any custom
    configuration. If any error occurs while manipulating handlers,
    it will be logged as an error and re-raised as a RuntimeError.
    """
    import logging
    try:
        root = logging.getLogger()
        # Remove and close existing handlers
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception as e:
                # Log handler removal failure and continue
                try:
                    logging.warning("Failed to remove/close handler %s: %s", handler, e)
                except Exception:
                    # If logging itself fails, silently ignore
                    pass
        # Reset log level to default
        root.setLevel(logging.WARNING)
        # Apply basic configuration if no handlers remain
        if not root.handlers:
            logging.basicConfig(level=logging.WARNING)
    except Exception as exc:
        # Attempt to log the error; ignore if logging is broken
        try:
            logging.error("Failed to reset logging configuration: %s", exc)
        except Exception:
            pass
        raise RuntimeError("Logging reset failed") from exc

