def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset current context
    try:
        if hasattr(self, "context"):
            self.context = {}
        else:
            self.context = {}
    except Exception:
        # Ensure context exists
        self.context = {}

    # Initialize bins
    bins = None
    try:
        init_val = getattr(self, "initial_value", None)
        make_bins_func = getattr(self, "make_bins", None)
        if init_val is not None:
            if callable(make_bins_func):
                try:
                    template = make_bins_func()
                    # Try to mimic size if template is iterable
                    try:
                        bins = [init_val for _ in template]
                    except TypeError:
                        bins = init_val
                except Exception:
                    bins = init_val
            else:
                bins = init_val
        else:
            if callable(make_bins_func):
                bins = make_bins_func()
    except Exception:
        bins = None

    # Assign bins
    self.bins = bins

def to_csv(self, separator=",", header=None):
        """Convert graph's points to CSV.

        Parameters
        ----------
        separator : str, optional
            Separator character used for fields. Defaults to ','.
        header : str or None, optional
            Optional header line that is written first. A newline will be
            appended automatically. If ``None``, no header is added.

        Returns
        -------
        str
            A CSV string containing the graph's points.

        Notes
        -----
        Each point is written as a line. The *coordinate* of the point
        is first converted to a string and joined by *separator*.  Then the
        elements of the point's *value* are appended. If *value* is not
        iterable (or is a string/bytes), it is treated as a scalar.
        """
        # Prepare the list of output lines.
        lines = []

        # Add optional header
        if header is not None:
            lines.append(str(header))

        # Attempt to retrieve the iterable of points.
        try:
            points_iter = getattr(self, "points", None)
            if points_iter is None:
                points_iter = iter(self)
            else:
                points_iter = iter(points_iter)
        except TypeError as exc:
            raise TypeError("The graph object does not provide an iterable of points.") from exc

        for point in points_iter:
            # Retrieve coordinate and value attributes, falling back to common alternative names.
            coord = getattr(point, "coordinate", None)
            if coord is None:
                coord = getattr(point, "coords", None)          # e.g. 'coords' as an alternative name
            if coord is None:
                coord = ()                                       # No coordinate information

            val = getattr(point, "value", None)
            if val is None:
                val = getattr(point, "values", None)            # e.g. 'values' as an alternative name
            if val is None:
                val = ()                                       # No value information

            # Convert coordinate to list of strings.
            try:
                coord_parts = [str(c) for c in coord]
            except TypeError:
                coord_parts = [str(coord)]

            # Determine how to extract value parts.
            if val is None or val == () or val == []:
                val_parts = []
            else:
                if isinstance(val, (str, bytes)):
                    val_parts = [str(val)]
                else:
                    try:
                        val_iter = iter(val)
                    except TypeError:
                        val_parts = [str(val)]
                    else:
                        val_parts = [str(v) for v in val_iter]

            # Construct the line and add it to the list.
            line = separator.join(coord_parts + val_parts)
            lines.append(line)

        # Join all lines with newline separator.
        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str) or not coord_name.strip():
        raise ValueError("coord_name must be a non-empty string")

    # Helper to determine if an object is iterable but not a string/bytes
    def _is_iterable(obj):
        return (
            hasattr(obj, "__iter__")
            and not isinstance(obj, (str, bytes))
        )

    # Attempt to locate the error data attribute
    err_obj = None
    attribute_patterns = [
        f"{coord_name}_err",
        f"{coord_name}_error",
        f"{coord_name}Error",
        f"{coord_name}Err",
        f"{coord_name}ERR",
    ]
    for attr_name in attribute_patterns:
        if hasattr(self, attr_name):
            err_obj = getattr(self, attr_name)
            break

    # Fallback to a possible dictionary of errors
    if err_obj is None and hasattr(self, "_error_dict"):
        if isinstance(self._error_dict, dict):
            err_obj = self._error_dict.get(coord_name)

    # If still not found, raise informative error
    if err_obj is None:
        raise AttributeError(
            f"Could not find error data for coordinate '{coord_name}'. "
            f"Checked attributes: {', '.join(attribute_patterns)} "
            f"and '_error_dict' if available."
        )

    # Gather indices where an error is present
    indices = []

    # If error object is scalar
    if isinstance(err_obj, (int, float)):
        if err_obj != 0 and not (isinstance(err_obj, float) and err_obj != err_obj):
            indices.append(0)
        return indices

    # If error object is iterable (list, tuple, numpy array, etc.)
    if _is_iterable(err_obj):
        for idx, val in enumerate(err_obj):
            try:
                # Skip missing or zero errors
                if val is None:
                    continue
                if isinstance(val, float):
                    # Treat NaN or zero as no error
                    if val == 0.0 or val != val:
                        continue
                elif isinstance(val, (int, complex)):
                    if val == 0:
                        continue
                else:
                    # For other types, rely on truthiness
                    if val:
                        indices.append(idx)
                    continue
                indices.append(idx)
            except Exception:
                # In case of unexpected exceptions during evaluation, skip entry
                continue
        return indices

    # If not iterable nor scalar, return empty list
    return indices

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # We assume FillRequest and Source are defined in the same module
    # or available in the context where this function is used.
    try:
        # Direct instances
        if isinstance(seq, Source):
            return False
        if isinstance(seq, FillRequest):
            return True

        # For iterables (excluding strings and bytes)
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
            # Avoid consuming already finished iterators by checking for emptiness implicitly
            for elem in seq:
                # Re-check if source or fill request while iterating
                if isinstance(elem, Source):
                    return False
                if isinstance(elem, FillRequest):
                    return True
        return False
    except Exception:
        # In case of invalid input or unexpected types, return False
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
        return callable(run_attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        # Ensure obj is not None and attributes exist
        if obj is None:
            return False
        fill_attr = getattr(obj, "fill", None)
        compute_attr = getattr(obj, "compute", None)
        # Check that both attributes are callable
        return callable(fill_attr) and callable(compute_attr)
    except Exception:
        # If any error occurs (e.g., attribute access fails), return False
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dictionary")

    def _diff(src, dst, lvl):
        result = {}
        for key, val in src.items():
            if key not in dst:
                # key only in d1, include it
                result[key] = val
            else:
                val2 = dst[key]
                # If both values are dicts, recurse depending on level
                if isinstance(val, dict) and isinstance(val2, dict):
                    if lvl == -1 or lvl > 1:
                        sub = _diff(val, val2, lvl - 1 if lvl > 0 else -1)
                        if sub:
                            result[key] = sub
                    else:  # lvl == 1: compare for equality only
                        if val != val2:
                            result[key] = val
                else:
                    # Non-dict values: include if differ
                    if val != val2:
                        result[key] = val
        return result

    if level == 0:
        # No recursion level specified; return empty diff
        return {}
    if level < -1:
        raise ValueError("level must be -1 (infinite) or a non-negative integer")
    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    # Normalize coordinate to a tuple
    try:
        if isinstance(coord, (int, float, complex)):
            coord = (coord,)
        else:
            coord = tuple(coord)
    except Exception:
        raise TypeError("coord must be a scalar or an iterable of coordinates")

    # Ensure the histogram has axes and a content array
    if not hasattr(self, "axes"):
        raise AttributeError("The histogram object must have an 'axes' attribute")
    if not hasattr(self, "content"):
        raise AttributeError("The histogram object must have a 'content' attribute")

    # Dimension check
    ndim = len(self.axes)
    if len(coord) != ndim:
        # Mismatch in dimensionality – do nothing
        return

    # Import numpy for efficient bin locating
    import numpy as np

    # Find bin indices for each dimension
    bin_indices = []
    for dim, val in enumerate(coord):
        axis = self.axes[dim]
        if hasattr(axis, "edges"):
            edges = axis.edges
        elif hasattr(axis, "bins"):
            # Some axis implementations store bins directly
            bins = axis.bins
            edges = np.concatenate([[bins[0] - (bins[1] - bins[0]) / 2],
                                    bins + (bins[1] - bins[0]) / 2])
        else:
            raise AttributeError(f"Axis at dimension {dim} has no 'edges' or 'bins' attribute")

        # Locate the bin using searchsorted
        try:
            idx = np.searchsorted(edges, val, side="right") - 1
        except Exception:
            # If searchsorted fails, ignore the fill
            return

        # Check bounds
        if idx < 0 or idx >= len(edges) - 1:
            # Out of range – ignore
            return
        bin_indices.append(idx)

    # Increment the selected bin by the given weight
    try:
        self.content[tuple(bin_indices)] += weight
    except Exception as exc:
        # If the content cannot accept the update, raise an informative error
        raise RuntimeError(f"Could not update histogram content: {exc}") from exc

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer_schema dict from a Kubernetes manifest dictionary.

    The function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``. For nested dictionaries the
    function is called recursively. Lists are processed element-wise:
    each element that is a dict is transformed recursively; other elements are
    replaced with ``None``. When ``first_level`` is ``True`` (i.e. the dictionary
    represents the whole observer_schema of a Kubernetes resource), the values
    of the identifying fields (`apiVersion`, `kind` and `metadata` with its
    `name` and optionally `namespace`) are copied from the manifest.

    Parameters
    ----------
    manifest_dict : dict
        Partial Kubernetes resources represented as a dictionary.
    first_level : bool, optional
        Flag indicating whether the input dictionary is the top-level
        observer schema of a resource. Default is ``False``.

    Returns
    -------
    dict
        A dictionary suitable for an observer_schema, with all leaf values
        set to ``None`` except for identifying fields when ``first_level``
        is ``True``.

    Raises
    ------
    TypeError
        If ``manifest_dict`` is not a dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected dict, got {type(manifest_dict).__name__}")

    # Helper to process lists
    def _process_list(lst):
        result = []
        for item in lst:
            if isinstance(item, dict):
                result.append(_process_dict(item))
            else:
                # non-dict/non-list element -> None
                result.append(None)
        return result

    # Helper to process nested dicts
    def _process_dict(d, is_top=False):
        result = {}
        # If top-level and identified fields are required, copy them
        if is_top:
            for key in ("apiVersion", "kind"):
                if key in d:
                    result[key] = d[key]
            # Metadata: copy name (and namespace if present)
            if "metadata" in d and isinstance(d["metadata"], dict):
                meta = {}
                if "name" in d["metadata"]:
                    meta["name"] = d["metadata"]["name"]
                if "namespace" in d["metadata"]:
                    meta["namespace"] = d["metadata"]["namespace"]
                result["metadata"] = meta
            # Do not process other tags of 'metadata' here
            # For any other keys, they will be processed normally below
        for k, v in d.items():
            if k in result:  # skip keys already copied (apiVersion, kind, metadata in top)
                continue
            if isinstance(v, dict):
                result[k] = _process_dict(v, False)
            elif isinstance(v, list):
                result[k] = _process_list(v)
            else:
                result[k] = None
        return result

    return _process_dict(manifest_dict, first_level)

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re
    from collections.abc import Mapping, Sequence, Iterable

    # Helper to convert a single params mapping/sequence based on placeholder order
    def _convert_params(sql_str, params, names_order=None):
        # If names_order is provided (named style), produce list of values in that order
        if names_order is not None:
            if not isinstance(params, Mapping):
                raise TypeError("Expected a mapping of name -> value for named parameters")
            # Ensure all required keys exist
            try:
                return [params[name] for name in names_order]
            except KeyError as e:
                raise KeyError(f"Missing parameter for placeholder {e}") from None
        else:
            # Ordinal style; params should be a sequence
            if not isinstance(params, Sequence):
                raise TypeError("Expected a sequence of values for ordinal parameters")
            return list(params)

    # Work with string representation for regex
    if isinstance(sql, bytes):
        try:
            sql_str = sql.decode(errors="surrogatepass")
        except Exception:
            # Fallback: treat as bytes and process as is
            sql_str = sql
    else:
        sql_str = sql

    # Determine style from first parameters
    # An empty many_params should return unchanged sql and empty list
    try:
        first_params = next(iter(many_params))
    except StopIteration:
        return sql, []

    if isinstance(first_params, Mapping):
        # Named placeholders
        pattern = re.compile(r"%\(([^)]+)\)s")
        names_order = pattern.findall(sql_str)

        # Replace named placeholders with '?' which is typical out-style for many drivers
        new_sql_str = pattern.sub("?", sql_str)

        # Convert each params mapping to list in order of names
        out_params = []
        for params in many_params:
            out_params.append(_convert_params(new_sql_str, params, names_order))
    else:
        # Ordinal / positional placeholders
        # Detect placeholders like '?' or '%s' or ':1'
        # For simplicity, replace any of these with '?' and treat sequence directly
        # We'll detect '?' and '%s' patterns
        # If the sql contains '?' only, we keep as is
        if "?" in sql_str:
            new_sql_str = sql_str
        elif "%s" in sql_str:
            new_sql_str = sql_str.replace("%s", "?")
        else:
            # Try numeric placeholders like :1, :2 etc.
            numeric_pattern = re.compile(r":(\d+)")
            if numeric_pattern.search(sql_str):
                new_sql_str = numeric_pattern.sub("?", sql_str)
            else:
                # No identifiable placeholder; assume '?' will be used
                new_sql_str = sql_str

        # All params should be sequences; convert to list
        out_params = []
        for params in many_params:
            out_params.append(_convert_params(new_sql_str, params))

    # Preserve original type
    if isinstance(sql, bytes):
        if isinstance(new_sql_str, str):
            # Encode back, prefer same encoding if possible
            new_sql = new_sql_str.encode("utf-8", errors="surrogatepass")
        else:
            new_sql = new_sql_str
    else:
        new_sql = new_sql_str

    return new_sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        import json

        # Resolve absolute path
        root = os.path.abspath(path)

        # Path must exist and be a directory
        if not os.path.isdir(root):
            return False

        # OCFL object must contain an ocfl-object.json file
        ocfl_file = os.path.join(root, "ocfl-object.json")
        if not os.path.isfile(ocfl_file):
            return False

        # Load and parse the OCFL object JSON
        try:
            with open(ocfl_file, "r", encoding="utf-8") as f:
                obj_data = json.load(f)
        except Exception:
            return False

        if not isinstance(obj_data, dict):
            return False

        # Required keys for a basic OCFL object (adjust as needed)
        required_keys = ["objectID", "tags", "versions", "configuration"]
        for key in required_keys:
            if key not in obj_data:
                return False

        # The content directory should exist
        content_dir = os.path.join(root, "content")
        if not os.path.isdir(content_dir):
            return False

        # There should be at least one version directory under content
        version_dirs = [
            d for d in os.listdir(content_dir)
            if os.path.isdir(os.path.join(content_dir, d))
        ]
        if not version_dirs:
            return False

        # Each version directory should contain a manifest.json file
        for vdir in version_dirs:
            manifest_path = os.path.join(content_dir, vdir, "manifest.json")
            if not os.path.isfile(manifest_path):
                return False

        return True
    except Exception:
        # Any unexpected error is treated as a validation failure
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Ensure prefix is a string
    try:
        prefix_str = str(prefix)
    except Exception:
        prefix_str = ''
    # Attempt to get the validator's status representation
    try:
        status = getattr(self, 'status', None)
    except Exception:
        status = None
    # Convert status to string safely
    try:
        status_str = str(status) if status is not None else ''
    except Exception:
        status_str = ''
    return f"{prefix_str}{status_str}"

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Ensure digests_used is an iterable of strings
        try:
            digests_used_set = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digest strings")
        # Collect all digests reported in the manifest
        present_digests = set()
        if manifest_files is None:
            manifest_files = []
        for entry in manifest_files:
            # Handle dictionary entries that may contain a 'digest' or 'digests' key
            if isinstance(entry, dict):
                if 'digest' in entry:
                    d = entry.get('digest')
                    if isinstance(d, str):
                        present_digests.add(d)
                elif 'digests' in entry:
                    digs = entry.get('digests')
                    if isinstance(digs, (list, set, tuple)):
                        for d in digs:
                            if isinstance(d, str):
                                present_digests.add(d)
                continue
            # Handle string entries – attempt to extract a digest from the filename
            if isinstance(entry, str):
                parts = entry.split('.')
                if len(parts) > 1:
                    candidate = parts[-1]
                    # Recognize commonly used digest lengths (MD5, SHA-256, etc.)
                    if len(candidate) in (32, 40, 64) and all(c in '0123456789abcdefABCDEF' for c in candidate):
                        present_digests.add(candidate.lower())
                continue
            # For any other type, skip silently
        # Determine missing digests (present in manifest but not listed as used)
        missing = present_digests - digests_used_set
        if missing:
            raise ValueError(f"Missing digests that are present in the manifest but not used: {missing}")
        # Optional: identify digests that are listed as used but not present in the manifest
        # This is not treated as an error here, but can be logged or processed as needed
        # unused = digests_used_set - present_digests
        # if unused:
        #     # Example: could log a warning or collect for further action
        #     pass
        return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Verify that prior is an InventoryValidator instance
    if prior is None:
        raise ValueError("prior argument cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure both objects have the expected inventory attribute
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both self and prior must have an 'inventory' attribute")

    # Coerce inventories to dictionaries if they are not
    try:
        self_inv = dict(self.inventory)
        prior_inv = dict(prior.inventory)
    except Exception as exc:
        raise ValueError("Failed to convert inventories to dictionaries") from exc

    # Check that every item in prior exists in the current inventory
    missing_keys = [key for key in prior_inv if key not in self_inv]
    if missing_keys:
        raise ValueError(f"Prior inventory is missing items in current inventory: {missing_keys}")

    # Optional: Validate that for each overlapping key, the prior value is not newer
    # (Assumes items are mapping-like and may contain a 'last_modified' timestamp)
    for key in prior_inv:
        prior_item = prior_inv[key]
        current_item = self_inv[key]
        # If both items have a 'last_modified' field that can be compared
        if isinstance(prior_item, dict) and isinstance(current_item, dict):
            prior_ts = prior_item.get("last_modified")
            current_ts = current_item.get("last_modified")
            if prior_ts is not None and current_ts is not None:
                try:
                    if current_ts < prior_ts:
                        raise ValueError((
                            f"For key {key}, current inventory's last_modified "
                            f"({current_ts}) is older than prior's last_modified ({prior_ts})"
                        ))
                except TypeError:
                    # If timestamps are not comparable, skip the check
                    pass

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        return {}
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    result = {}

    def _collect(node):
        if not isinstance(node, dict):
            return
        # Check if this dict represents a state with a matching version
        if node.get('state') == version:
            files = node.get('files')
            if isinstance(files, dict):
                for logical, content_file in files.items():
                    if logical is None or content_file is None:
                        continue
                    if logical not in result:
                        result[logical] = set()
                    result[logical].add(content_file)
        # Recurse into all values
        for value in node.values():
            _collect(value)

    _collect(inventory)
    return result

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language code
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("The 'lang' parameter must be a non-empty string.")
    # Validate file_path
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("The 'file_path' parameter must be a non-empty string.")
    # Basic check for a PDF file extension (optional)
    if not file_path.lower().endswith('.pdf'):
        raise ValueError("The 'file_path' must point to a PDF file.")
    # Initialize renditions dictionary if it doesn't exist
    if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
        self.renditions = {}
    # Add or overwrite the rendition for the given language
    self.renditions[lang] = file_path
    # Optionally, you could update metadata or other structures here
    return None

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string representing a file path.")
    try:
        zipfile = __import__("zipfile")
        os = __import__("os")
        with zipfile.ZipFile(zip_path, "r") as zf:
            result = {}
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                fname = info.filename
                if not fname.lower().endswith(".xml"):
                    continue
                try:
                    content_bytes = zf.read(info)
                except Exception as e:
                    # If file cannot be read, skip it
                    continue
                try:
                    content = content_bytes.decode("utf-8", errors="replace")
                except Exception:
                    # If decoding fails, store raw bytes
                    content = content_bytes
                base = os.path.splitext(os.path.basename(fname))[0]
                result.setdefault(base, []).append(content)
            return result
    except FileNotFoundError as e:
        raise RuntimeError(f"File not found: {zip_path}") from e
    except zipfile.BadZipFile as e:
        raise RuntimeError(f"Bad zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    The function expects a string and replaces every occurrence of
    ``w:st="`` with ``w-st="``. It raises a TypeError if the input
    is not a string.
    """
    if not isinstance(content, str):
        raise TypeError(f"Expected a string, got {type(content).__name__}")

    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        # In the unlikely event that replace fails, re-raise a RuntimeError
        raise RuntimeError(f"Failed to replace namespace prefix: {e}") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        raise ValueError("node cannot be None")
    if pubdate_xpaths is None:
        return None
    # Ensure we can iterate over pubdate_xpaths
    try:
        iterator = iter(pubdate_xpaths)
    except TypeError:
        # Not iterable, treat as a single xpath string
        pubdate_xpaths = [pubdate_xpaths]
        iterator = iter(pubdate_xpaths)

    # Check that the node supports XPath evaluation
    if not hasattr(node, "xpath"):
        raise ValueError("Provided node does not support xpath evaluation")

    for xpath_expr in iterator:
        # Skip non-string xpath expressions
        if not isinstance(xpath_expr, str):
            continue
        try:
            result = node.xpath(xpath_expr)
        except Exception:
            # If an XPath error occurs, skip to next expression
            continue
        if not result:
            continue  # No match for this xpath
        # Take the first match
        first = result[0]
        # Prefer the text content if the result is an Element
        if hasattr(first, "text") and not isinstance(first, (str, bytes, int, float, bool)):
            return first.text if first.text is not None else str(first)
        # Otherwise, return the string representation of the value
        return str(first)
    # No matches found
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    if not isinstance(issue, str):
        return (None, None)
    # Remove surrounding tags if present
    txt = re.sub(r'^<[^>]+>|</[^>]+>$', '', issue).strip()
    if not txt:
        return (None, None)

    # Find the first numeric part that is not part of a supplement indicator
    # Identify supplement word
    sup_match = re.search(r'(?i)(suppl|s|spe|supp|supl)[\.\s]*([0-9]+)?', txt)
    sup_val = None
    if sup_match:
        if sup_match.group(2):
            try:
                sup_val = int(sup_match.group(2))
            except ValueError:
                sup_val = None
        else:
            sup_val = 1

    # Determine number value
    number_val = None
    # If there's a hyphen between numbers, return the whole range as string
    if '-' in txt:
        nums = re.findall(r'\d+', txt)
        if len(nums) >= 2:
            number_val = f"{nums[0]}-{nums[1]}"
    else:
        # Find first number not immediately preceded by a supplement word
        first_num = re.search(r'\d+', txt)
        if first_num:
            # Check preceding context
            context_before = txt[:first_num.start()].strip()
            if not re.search(r'(?i)(suppl|s|spe|supp|supl)$', context_before):
                try:
                    number_val = int(first_num.group())
                except ValueError:
                    number_val = None

    return (number_val, sup_val)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if indent < 0:
        raise ValueError("indent must be non‑negative")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    # Helper to format individual values
    def _format_value(val, depth):
        try:
            # Avoid recursive loops by tracking ids
            seen = _format_value.seen
        except AttributeError:
            _format_value.seen = set()
            seen = _format_value.seen
        val_id = id(val)
        if val_id in seen:
            return '<recursion>'
        if hasattr(val, "pretty") and callable(val.pretty):
            seen.add(val_id)
            try:
                return val.pretty(indent=depth, debug=debug)
            finally:
                seen.remove(val_id)
        # Handle basic containers recursively for readability
        if isinstance(val, (list, tuple, set)):
            inner = ", ".join(_format_value(v, depth + 1) for v in val)
            return f"{type(val).__name__}([{inner}])"
        if isinstance(val, dict):
            items = ", ".join(f"{_format_value(k, depth+1)}: {_format_value(v, depth+1)}"
                              for k, v in val.items())
            return f"dict({{{items}}})"
        # Fallback
        return repr(val)

    # Gather attributes
    try:
        attrs = vars(self)
    except TypeError:
        # No __dict__, fall back to dir filtering
        attrs = {k: getattr(self, k) for k in dir(self)
                 if not k.startswith('_') and not callable(getattr(self, k))}
    lines = []
    indent_str = "  " * indent
    header = f"{indent_str}{self.__class__.__name__}("
    lines.append(header)
    # Attributes formatting
    for name, value in attrs.items():
        if debug:
            val_str = f"{name} ({type(value).__name__}): { _format_value(value, indent + 1)}"
        else:
            val_str = f"{name} = { _format_value(value, indent + 1)}"
        lines.append(f"{'  ' * (indent + 1)}{val_str}")
    lines.append(f"{indent_str})")
    return "\n".join(lines)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions to identify expression types
    def _is_and(expr):
        return hasattr(expr, "func") and getattr(expr.func, "__name__", None) == "And"

    def _is_or(expr):
        return hasattr(expr, "func") and getattr(expr.func, "__name__", None) == "Or"

    def _is_not(expr):
        return hasattr(expr, "func") and getattr(expr.func, "__name__", None) == "Not"

    def _absorb_expr(expr):
        """Apply absorption rules to a single expression."""
        try:
            # Absorption for AND: A & (A | B)
            if _is_and(expr):
                a, b = expr.args
                if _is_or(b):
                    if a == b.args[0] or a == b.args[1]:
                        return a
                # Negative absorption: A & (~A | B) = A & B
                if _is_or(b):
                    for sub in b.args:
                        if _is_not(sub) and sub.args[0] == a:
                            other = [s for s in b.args if s != sub]
                            if other:
                                return expr.func(a, other[0])
        except Exception:
            pass

        try:
            # Absorption for OR: A | (A & B)
            if _is_or(expr):
                a, b = expr.args
                if _is_and(b):
                    if a == b.args[0] or a == b.args[1]:
                        return a
                # Negative absorption: A | (~A & B) = A | B
                if _is_and(b):
                    for sub in b.args:
                        if _is_not(sub) and sub.args[0] == a:
                            other = [s for s in b.args if s != sub]
                            if other:
                                return expr.func(a, other[0])
        except Exception:
            pass

        # No simplification possible
        return expr

    # Validate input
    if args is None:
        return list()
    if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
        raise TypeError("args must be an iterable of expressions")

    result = []
    for expr in args:
        result.append(_absorb_expr(expr))
    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate hook
    if hook is None:
        raise ValueError("hook must not be None")
    # Ensure registry exists
    if not hasattr(self, "_registry"):
        self._registry = {}
    # Verify hook can be used as a dict key
    try:
        hash(hook)
    except TypeError as exc:
        raise TypeError(f"hook {hook!r} must be hashable to be registered") from exc

    def decorator(fn):
        if not callable(fn):
            raise TypeError("handler must be callable")
        listeners = self._registry.setdefault(hook, [])
        # Avoid duplicate registrations
        if fn not in listeners:
            listeners.append(fn)
        return fn

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        name = namefunc()
    except Exception as exc:
        raise
    # If already bytes, return unchanged
    if isinstance(name, bytes):
        return name
    # Check if name is a unicode string
    try:
        is_unicode = isinstance(name, unicode)  # noqa: F821
    except NameError:  # Python 3
        is_unicode = isinstance(name, str)
    if is_unicode:
        try:
            return name.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Failed to encode tzname to bytes: {e}") from e
    # In Python 2, if name is a byte string (str), return it
    if isinstance(name, str):
        return name
    raise TypeError(f"tzname function returned unsupported type {type(name)!r}")

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default version information
    default = {"full": "0.0.0", "short": "0", "dev": False}
    try:
        import sys
        # 1. Try to obtain __version__ attribute from this module if available
        module = sys.modules[__name__]
        if hasattr(module, "__version__"):
            full_version = getattr(module, "__version__")
        else:
            # 2. Fallback to importlib.metadata to get distribution version
            try:
                import importlib.metadata as importlib_metadata  # Python ≥3.8
            except Exception:
                try:
                    import importlib_metadata  # Older versions
                except Exception as exc:
                    raise RuntimeError("No metadata provider available") from exc
            # Determine a reasonable distribution name
            dist_name = __package__ or __name__.split(".")[0]
            try:
                full_version = importlib_metadata.version(dist_name)
            except Exception as exc:
                raise RuntimeError(f"Cannot find distribution '{dist_name}'") from exc
        if not isinstance(full_version, str) or not full_version:
            raise ValueError("Invalid version string")
        # 3. Derive short version (strip any post-release or local version)
        short_version = full_version.split("-", 1)[0]
        # 4. Basic dev detection: look for dev, a, b, rc tags
        tags = ["dev", "a", "b", "rc"]
        dev_flag = any(any(part.endswith(tag) for tag in tags) for part in short_version.split("."))
        return {"full": full_version, "short": short_version, "dev": dev_flag}
    except Exception:
        return default

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not callable(method):
        raise TypeError("method must be callable")
    # Initialize registry if it doesn't exist
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    # Prevent duplicate registration
    if vcs in register_vcs_handler._registry:
        raise ValueError(f"Handler for vcs '{vcs}' is already registered")
    # Register the method
    register_vcs_handler._registry[vcs] = method
    # Mark the method with attributes for introspection
    setattr(method, "__is_vcs_handler__", True)
    setattr(method, "__vcs__", vcs)
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        # Obtain the collection of objects to validate
        get_objs = getattr(self, 'get_objects', None)
        if callable(get_objs):
            objects = get_objs()
        else:
            # Fall back to a direct attribute that might hold objects
            objects = getattr(self, 'objects', [])
    except Exception as e:
        if show_warnings:
            print(f"Unable to retrieve objects for validation: {e}")
        return num_objects, good_objects

    try:
        # Ensure we have an iterable object list
        iterator = iter(objects)
    except Exception as e:
        if show_warnings:
            print(f"Objects are not iterable: {e}")
        return num_objects, good_objects

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                validate = getattr(self, 'validate_object', lambda o: True)
                if callable(validate):
                    is_valid = bool(validate(obj))
                else:
                    is_valid = bool(validate)
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Error validating object {obj}: {e}")

        # Check digest if requested and object passed previous checks
        if is_valid and check_digests:
            try:
                check_digest = getattr(self, 'check_digest', lambda o: True)
                if callable(check_digest):
                    is_valid = bool(check_digest(obj))
                else:
                    is_valid = bool(check_digest)
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Error checking digest for object {obj}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    # Normalise path
    try:
        path = os.path.abspath(path)
    except Exception as e:
        return f"error: invalid path - {e}"

    if not os.path.exists(path):
        return "error: path does not exist"

    try:
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Check for Namaste files named exactly "0=*"
            # Only the top-level entries are inspected.
            try:
                for entry in os.listdir(path):
                    if entry.startswith("0="):
                        # Found Namaste file, assume this is an object directory.
                        return "object"
            except Exception as e:
                return f"error: cannot list directory contents - {e}"
            # No Namaste files found, assume storage root
            return "root"
        else:
            return "error: path is neither file nor directory"
    except Exception as e:
        return f"error: unexpected error - {e}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate that params is a dictionary
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # No bug_ids to amend; return params unchanged
    if bug_ids is None:
        return params

    try:
        # Handle the case where bug_ids is a string that may contain commas
        if isinstance(bug_ids, str):
            # If the string contains commas, interpret it as a list
            if "," in bug_ids:
                ids = [id_.strip() for id_ in bug_ids.split(",") if id_.strip()]
                if ids:
                    params["ids"] = ",".join(ids)
                return params
            # Otherwise treat it as a single id
            params["id"] = bug_ids
            return params

        # Handle iterable bug_ids (list, tuple, set, etc.)
        if isinstance(bug_ids, (list, tuple, set)):
            ids = [str(item).strip() for item in bug_ids if item is not None]
            if ids:
                params["ids"] = ",".join(ids)
            return params

        # For other types (e.g., int, float), treat as a single id
        params["id"] = str(bug_ids)
        return params

    except Exception as exc:
        raise ValueError(f"Error amending Bugzilla params: {exc}") from exc

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        # Ensure parser has the expected structure
        if not hasattr(parser, "_actions"):
            raise TypeError("Expected an argparse.ArgumentParser instance")
        flags = []
        seen = set()
        for action in parser._actions:
            if not hasattr(action, "option_strings"):
                continue
            for opt in action.option_strings:
                if opt not in seen:
                    seen.add(opt)
                    flags.append(opt)
        return " ".join(flags)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags: {exc}") from exc

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to merge two MappingNode instances recursively
    def merge_mapping_nodes(existing_map, new_map):
        # Ensure both are MappingNode-like objects; otherwise, the caller should have handled
        try:
            merged_items = _merge_node_tuples(existing_map.value, new_map.value)
            return type(existing_map)(tag=existing_map.tag, value=merged_items)
        except Exception:
            # Fallback to new_map if any error occurs
            return new_map

    # Helper to merge two lists of (ScalarNode, Node) tuples
    def _merge_node_tuples(list1, list2):
        result = list(list1)  # start with existing list
        for key_node, val_node in list2:
            key = key_node.value
            idx = None
            for i, (k_node, _) in enumerate(result):
                if k_node.value == key:
                    idx = i
                    break
            if idx is not None:
                existing_key, existing_val = result[idx]
                if isinstance(val_node, type(existing_val)) and isinstance(existing_val, type(val_node)) and hasattr(val_node, 'value') and isinstance(val_node.value, list) and isinstance(existing_val.value, list):
                    # Likely both are MappingNode
                    merged_map = merge_mapping_nodes(existing_val, val_node)
                    result[idx] = (existing_key, merged_map)
                else:
                    # Replace with new value (last wins)
                    result[idx] = (existing_key, val_node)
            else:
                result.append((key_node, val_node))
        return result

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')
    merged = []
    for item in nodes:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise ValueError('Each element in nodes must be a tuple of (ScalarNode, Node)')
        key_node, val_node = item
        key = key_node.value
        idx = None
        for i, (k_node, _) in enumerate(merged):
            if k_node.value == key:
                idx = i
                break
        if idx is not None:
            existing_key, existing_val = merged[idx]
            if isinstance(val_node, type(existing_val)) and isinstance(existing_val, type(val_node)) and hasattr(val_node, 'value') and isinstance(val_node.value, list) and isinstance(existing_val.value, list):
                # Merge MappingNodes
                merged_map = merge_mapping_nodes(existing_val, val_node)
                merged[idx] = (existing_key, merged_map)
            else:
                merged[idx] = (existing_key, val_node)
        else:
            merged.append((key_node, val_node))
    return merged

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    """
    try:
        if parser is None or not hasattr(parser, "_actions"):
            raise TypeError("Expected an argparse.ArgumentParser instance")
        flags = []
        for action in parser._actions:
            # option_strings is a list of flag strings for this action, empty for positional arguments
            if getattr(action, "option_strings", None):
                flags.extend(action.option_strings)
        # Join the flags preserving the defined order
        return " ".join(flags)
    except Exception as exc:
        # If an unexpected error occurs, return an empty string to avoid crashing callers
        return ""

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        # Import the standard library modules needed to discover entry points.
        import importlib.metadata as importlib_metadata  # Python 3.8+
    except Exception:  # pragma: no cover
        try:
            # Fall back to the backport for older Python versions.
            import importlib_metadata
        except Exception:  # pragma: no cover
            # If we cannot import metadata, we cannot produce a completion script.
            return ''

    # Locate the console script entry point for borgmatic.
    try:
        entry_points = importlib_metadata.entry_points()
        # In Python 3.10+, entry_points() returns a mapping; in older versions it returns a list.
        if isinstance(entry_points, dict):
            console_scripts = entry_points.get('console_scripts', [])
        else:
            console_scripts = [ep for ep in entry_points if ep.group == 'console_scripts']
    except Exception:  # pragma: no cover
        return ''

    borg_entry = None
    for ep in console_scripts:
        if getattr(ep, 'name', None) == 'borgmatic':
            borg_entry = ep
            break

    if borg_entry is None:
        # Could not find the borgmatic console script entry point.
        return ''

    # Attempt to import the module that defines the command‑line parser.
    try:
        module_name, _, func_name = borg_entry.value.partition(':')
        if not module_name or not func_name:
            return ''
        module = __import__(module_name, fromlist=[func_name])
        entry_func = getattr(module, func_name)
    except Exception:  # pragma: no cover
        return ''

    # Many packaging layouts expose a global argparse.ArgumentParser instance named `parser`.
    # Try to locate it; if not found, we cannot introspect commands and will fall back to a
    # generic completion script.
    parser = None
    for attr in ('parser', 'argparse_parser'):
        try:
            parser = getattr(module, attr)
            if parser is not None:
                break
        except Exception:
            continue

    # If we cannot find a parser instance, return a minimal completion script.
    if not isinstance(parser, type):
        parser = None

    if parser is None:
        script = (
            '# Bash completion for borgmatic\n'
            'borgmatic_completion() {\n'
            '    COMPREPLY=()\n'
            '    current="\\${COMP_WORDS[COMP_CWORD]}"\n'
            '    if [[ $current == -* ]]; then\n'
            '        COMPREPLY=( $(compgen -W "-h --help" -- $current) )\n'
            '    fi\n'
            '}\n'
            'complete -F borgmatic_completion borgmatic\n'
        )
        return script

    # Create a mapping of sub‑commands to their own parsers if possible.
    subparsers = {}
    for action in getattr(parser, "_actions", []):
        if isinstance(action, type(parser._get_subactions()[0] if parser._get_subactions() else None)):
            for choice, sub_action in getattr(action, "_name_parser_map", {}).items():
                subparsers[choice] = sub_action

    # Build the completion hint for sub‑commands and options.
    commands = sorted(subparsers.keys())
    options = []
    for action in getattr(parser, "_actions", []):
        if isinstance(action, type) and hasattr(action, "option_strings"):
            for opt in getattr(action, "option_strings", []):
                if opt.startswith("-"):
                    options.append(opt)

    script_parts = [
        '# Bash completion for borgmatic',
        'borgmatic_completion() {',
        '    local cur prev opts'
    ]
    script_parts.append('    COMPREPLY=()')
    script_parts.append('    cur="${COMP_WORDS[COMP_CWORD]}"')
    script_parts.append('    prev="${COMP_WORDS[COMP_CWORD-1]}"')

    # If the previous word is a command that has its own parser, use its options.
    if commands:
        cmd_options_map = {}
        for cmd, sub_parser in subparsers.items():
            opts = []
            for act in getattr(sub_parser, "_actions", []):
                if hasattr(act, "option_strings"):
                    opts.extend(act.option_strings)
            cmd_options_map[cmd] = sorted(opts)

    script_parts.append('    if [[ ${#COMP_WORDS[@]} -gt 1 ]]; then')
    script_parts.append('        case "$prev" in')
    for cmd in commands:
        script_parts.append(f'            {cmd})')
        opts = sorted(cmd_options_map.get(cmd, []))
        if opts:
            script_parts.append('                opts="{}"'.format(" ".join(opts)))
        else:
            script_parts.append('                opts=""')
        script_parts.append('                COMPREPLY=( $(compgen -W "$opts" -- $cur) );')
        script_parts.append('                return 0;;')
    script_parts.append('        esac')
    script_parts.append('    fi')

    # Default completions for top‑level commands and global options.
    top_level_opts = sorted(options)
    commands_str = " ".join(commands)
    opts_str = " ".join(top_level_opts)
    if commands or opts_str:
        script_parts.append('    opts="{}"'.format(commands_str + (" " + opts_str if opts_str else "")))
        script_parts.append('    COMPREPLY=( $(compgen -W "$opts" -- $cur) );')
    script_parts.append('}')
    script_parts.append('complete -F borgmatic_completion borgmatic')

    return "\n".join(script_parts)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Dynamically import needed modules to avoid static import statements
    sys = __import__('sys')
    argparse_module = __import__('argparse')
    Namespace = getattr(argparse_module, 'Namespace')

    # Determine the argument list to parse
    if unparsed_arguments:
        args = list(unparsed_arguments)
    else:
        # Exclude the script name itself
        args = sys.argv[1:]

    # Helper to create a Namespace from a list of values
    def build_namespace(values):
        ns = Namespace()
        # Store values as a single attribute 'args' (list)
        setattr(ns, 'args', values)
        return ns

    # If there are no arguments, return empty namespace under 'global'
    if not args:
        return {'global': Namespace()}

    # Identify potential subparser: the first non-option token
    subparser_name = None
    remaining_args = args
    if args[0] and not args[0].startswith('-'):
        subparser_name = args[0]
        remaining_args = args[1:]

    # Create namespace for global or subparser arguments
    ns = build_namespace(remaining_args)

    if subparser_name:
        return {subparser_name: ns}
    else:
        return {'global': ns}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Normalise inputs
    if unparsed_arguments is None:
        unparsed_arguments = []
    else:
        try:
            if not isinstance(unparsed_arguments, (list, tuple)):
                unparsed_arguments = list(unparsed_arguments)
        except Exception:
            unparsed_arguments = []

    if not isinstance(subparsers, dict):
        subparsers = {}

    parsed_map = {}
    claimed_args = set()

    for name, parser in subparsers.items():
        try:
            parsed, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_map[name] = parsed
            # Arguments that this parser successfully consumed
            consumed = set(unparsed_arguments) - set(remaining)
            claimed_args.update(consumed)
        except Exception:
            # If parsing fails (e.g., due to missing required args), record an empty namespace
            try:
                from argparse import Namespace
                parsed_map[name] = Namespace()
            except Exception:
                parsed_map[name] = {}

    # Remaining arguments that were not claimed by any parser
    remaining_args = [arg for arg in unparsed_arguments if arg not in claimed_args]

    return parsed_map, remaining_args

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("The input must be an iterable of dictionaries, not None.")
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Input must be an iterable of dictionaries.")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Element {d!r} is not a dictionary.")
        for k, v in d.items():
            if not isinstance(v, (int, float, complex)):
                raise TypeError(f"Value for key {k!r} must be a numeric type, got {type(v).__name__}.")
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate url
    if url is None:
        raise TypeError("url must not be None")
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    # If no args provided, return url unchanged
    if not url_args:
        return url
    if not isinstance(url_args, (dict,)):
        raise TypeError(f"url_args must be a dict, got {type(url_args).__name__}")
    # Perform replacements
    result = url
    for key, value in url_args.items():
        if key is None:
            continue
        placeholder = "{" + str(key) + "}"
        replace_val = "" if value is None else str(value)
        result = result.replace(placeholder, replace_val)
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    try:
        import argparse
    except Exception:
        return ''
    if not isinstance(parser, argparse.ArgumentParser):
        return ''
    try:
        flags = []
        for action in getattr(parser, '_actions', []):
            # action.option_strings may be an empty list for positional arguments
            option_strings = getattr(action, 'option_strings', None)
            if option_strings:
                flags.extend(option_strings)
        return ' '.join(flags)
    except Exception:
        # In case of unexpected errors, return empty string
        return ''

def int_to_string(number: int, alphabet: list, padding: int | None = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate arguments
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")

    if not hasattr(alphabet, "__len__") or len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two characters")

    if not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("all elements of alphabet must be strings")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    base = len(alphabet)
    neg = number < 0
    num = abs(number)

    # Special case for zero
    if num == 0:
        digit_str = alphabet[0]
    else:
        digits = []
        while num:
            num, rem = divmod(num, base)
            digits.append(alphabet[rem])
        digit_str = "".join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(digit_str) < padding:
        pad_len = padding - len(digit_str)
        digit_str = alphabet[0] * pad_len + digit_str

    return ("-" if neg else "") + digit_str

def _replace_register(flow_params, register_number, register_value):
    """
    Replace the value associated with ``register_value`` in the dictionary ``flow_params``
    by the supplied ``register_number``. The replacement is performed recursively,
    so nested dictionaries and lists are also processed.

    Parameters
    ----------
    flow_params : dict
        Dictionary containing defined flows.  The function does not modify the
        input dictionary in place; instead it returns a new dictionary.
    register_number : int or str
        The value that will replace the current value of the key ``register_value``.
    register_value : hashable
        The key in the dictionary whose value should be replaced.

    Returns
    -------
    dict
        A new dictionary identical to ``flow_params`` except that all occurrences
        of ``register_value`` have their values replaced by ``register_number``.

    Raises
    ------
    TypeError
        If ``flow_params`` is not a dictionary.
    ValueError
        If any of the arguments is ``None``.
    """
    if flow_params is None or register_number is None or register_value is None:
        raise ValueError("None values are not allowed for flow_params, register_number, or register_value")

    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    def _replace_recursive(obj):
        if isinstance(obj, dict):
            new_obj = {}
            for key, value in obj.items():
                if key == register_value:
                    new_obj[key] = register_number
                else:
                    new_obj[key] = _replace_recursive(value)
            return new_obj
        elif isinstance(obj, list):
            return [_replace_recursive(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(_replace_recursive(item) for item in obj)
        else:
            return obj

    try:
        return _replace_recursive(flow_params)
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Error while replacing register values: {exc}") from exc

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    # Validate input types
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    # Perform replacement
    return value.replace(".", arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"subclasses() expected a type, got {type(cls).__name__}")
    result = set()
    try:
        subs = cls.__subclasses__()
    except Exception as exc:
        raise TypeError(f"Unable to retrieve subclasses of {cls}") from exc
    for sub in subs:
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("Alphabet must be a list or tuple of characters")

    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate characters")

    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    if not isinstance(string, str):
        raise TypeError("Input must be a string")

    s = string.strip()
    if not s:
        raise ValueError("Input string is empty")

    sign = 1
    if s[0] in '+-':
        sign = -1 if s[0] == '-' else 1
        s = s[1:]
        if not s:
            raise ValueError("No digits after sign")

    result = 0
    for ch in s:
        if ch not in char_to_value:
            raise ValueError(f"Character {ch!r} not found in alphabet")
        result = result * base + char_to_value[ch]

    return sign * result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    # Primary check: use os.uname() if available
    try:
        return os.uname().sysname.lower() == 'darwin'
    except AttributeError:
        # os.uname() might not exist on non-Unix platforms
        try:
            import sys
            return sys.platform.lower().startswith('darwin')
        except Exception:
            # Fallback: uncertain, return False
            return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Expected a dictionary for `item`")
    result = {}
    # Regex special characters that need to be escaped
    special_chars = {'.', '^', '$', '+', '?', '{', '}', '[', ']', '\\', '|', '(', ')'}
    for key, value in item.items():
        if not isinstance(key, str):
            # skip non-string keys
            result[key] = value
            continue
        # Build regex pattern from key
        pattern_parts = ['^']
        for ch in key:
            if ch == '*':
                pattern_parts.append('.*')
            elif ch in special_chars:
                pattern_parts.append('\\' + ch)
            else:
                pattern_parts.append(ch)
        pattern_parts.append('$')
        regex_key = ''.join(pattern_parts)
        result[regex_key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    return re.sub(r"(^['\"]|['\"]$)", "", name)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Ensure archive exists
    try:
        subprocess.run(["test", "-f", archive_path], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError:
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Prepare temporary extraction directory
    tmp_path_str = str(tmp_path)
    # Normalize tmp_path without trailing slash
    tmp_dir = tmp_path_str.rstrip("/")
    # Derive target directory name
    if filename:
        subdir_name = filename
    else:
        # Get basename of archive
        base = archive_path.split("/")[-1]
        # Strip known archive extensions
        for ext in (".tar.gz", ".tar.bz2", ".tar.xz", ".zip", ".tar", ".tgz", ".tbz2", ".txz"):
            if base.endswith(ext):
                base = base[: -len(ext)]
                break
        else:
            # Fallback: strip everything after last dot
            base = base.split(".")[0]
        subdir_name = base
    extraction_dir = f"{tmp_dir}/{subdir_name}"

    # Create extraction directory if needed
    try:
        subprocess.run(["mkdir", "-p", extraction_dir], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError:
        raise RuntimeError(f"Could not create extraction directory: {extraction_dir}")

    # Determine extraction command based on archive type
    try:
        if archive_path.endswith(".zip"):
            # unzip will create subdirectories inside the extraction dir
            cmd = ["unzip", "-q", "-d", extraction_dir, archive_path]
        elif archive_path.endswith((".tar.gz", ".tgz")):
            cmd = ["tar", "-xzf", archive_path, "-C", extraction_dir]
        elif archive_path.endswith((".tar.bz2", ".tbz2")):
            cmd = ["tar", "-xjf", archive_path, "-C", extraction_dir]
        elif archive_path.endswith((".tar.xz", ".txz")):
            cmd = ["tar", "-xJf", archive_path, "-C", extraction_dir]
        elif archive_path.endswith(".tar"):
            cmd = ["tar", "-xf", archive_path, "-C", extraction_dir]
        else:
            raise ValueError(f"Unsupported archive format: {archive_path}")

        subprocess.run(cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to extract archive {archive_path}: {exc}") from exc

    return extraction_dir

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files,
    and return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.check_output(
            ['git', 'ls-files', '--others', '--exclude-standard'],
            stderr=subprocess.DEVNULL
        )
        files = result.decode('utf-8').splitlines()
        files = sorted([f for f in files if f.strip()])
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string or None")

    parts = frequency.strip().lower().split()
    if len(parts) < 2:
        raise ValueError(f"Unable to parse frequency: '{frequency}'")

    number_part, unit_part = parts[0], parts[1]
    try:
        amount = float(number_part)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: '{frequency}'")

    # Normalize unit to singular form
    if unit_part.endswith('s'):
        unit = unit_part[:-1]
    else:
        unit = unit_part

    unit_map = {
        'day': ('days',),
        'hour': ('hours',),
        'minute': ('minutes',),
        'second': ('seconds',),
        'week': ('weeks',),
        'millisecond': ('milliseconds',),
        'microsecond': ('microseconds',)
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit in frequency: '{frequency}'")

    kwarg_name = unit_map[unit][0]
    kwargs = {kwarg_name: amount}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Basic validation
    if not host or not isinstance(host, (str, bytes)):
        return False
    # Ensure we are working with a string
    host_str = host.decode() if isinstance(host, bytes) else host.strip()
    # Strip surrounding brackets that may appear with IPv6 literals
    if host_str.startswith('[') and host_str.endswith(']'):
        host_str = host_str[1:-1]
    # Normalize common localhost representations
    known_local = {'localhost', '127.0.0.1', '::1'}
    if host_str.lower() in known_local:
        return True
    try:
        addrinfos = socket.getaddrinfo(host_str, None)
    except (socket.gaierror, socket.herror):
        return False
    import ipaddress
    for ai in addrinfos:
        # ai[4] is a tuple: (addr, port, flowinfo, scopeid) for IPv6 or (addr, port) for IPv4
        ip = ai[4][0]
        try:
            if ipaddress.ip_address(ip).is_loopback:
                return True
        except ValueError:
            continue
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string containing YAML content")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer representing file permissions")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Check existence and overwrite flag
    if os.path.exists(config_filename):
        if not overwrite:
            raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")
        # If overwrite is True, we will replace the file; no further action needed

    # Ensure target directory exists
    dir_name = os.path.dirname(config_filename)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except Exception as e:
            raise OSError(f"Failed to create directories for '{config_filename}': {e}")

    # Write the file
    try:
        with open(config_filename, 'w', encoding='utf-8') as fh:
            fh.write(rendered_config)
        # Set the file mode
        try:
            os.chmod(config_filename, mode)
        except Exception as e:
            # If chmod fails we warn but do not abort
            raise OSError(f"Failed to set mode {oct(mode)} on '{config_filename}': {e}")
    except Exception as e:
        # Clean up partially written file if possible
        try:
            if os.path.exists(config_filename):
                os.remove(config_filename)
        except Exception:
            pass  # ignore cleanup errors
        raise OSError(f"Failed to write configuration to '{config_filename}': {e}")
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine name and default from matcher
    if isinstance(matcher, str):
        name, default = matcher, None
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) == 1:
            name, default = matcher[0], None
        elif len(matcher) == 2:
            name, default = matcher[0], matcher[1]
        else:
            raise ValueError("matcher must be a string or a list/tuple of length 1 or 2")
    else:
        raise TypeError("matcher must be a string or a list/tuple")

    if not isinstance(name, str):
        raise TypeError("environment variable name must be a string")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise EnvironmentError(f"Environment variable '{name}' not set and no default provided")
    return value

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        # Check if already an IPv4Address instance
        if isinstance(target, ipaddress.IPv4Address):
            return True
        # Attempt to create an IPv4Address; this will raise if invalid
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError, TypeError):
        # Any of these exceptions indicates target is not a valid IPv4 address
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in a transitive hierarchy defined by triples of the form
    (child, prop, parent). A root is a node that never appears as a child.
    If ``roots`` is supplied, the result is intersected with it.
    """
    # Quick exit for invalid inputs
    if graph is None or prop is None:
        return set()

    # Gather all children and parents for the given property
    try:
        start_pattern = (None, prop, None)  # matches all triples with this predicate
        triples_iter = graph.triples(start_pattern)
    except Exception as exc:
        raise ValueError(
            "The supplied graph does not support triples with a predicate mask."
        ) from exc

    children: Set["Node"] = set()
    parents: Set["Node"] = set()
    for subj, _, obj in triples_iter:
        children.add(subj)
        parents.add(obj)

    # Roots are parents that never appear as a child
    root_candidates = parents.difference(children)

    # If an explicit set of roots was provided, intersect with it
    if roots is not None:
        try:
            roots_set = set(roots)
        except Exception as exc:
            raise TypeError("The 'roots' argument must be an iterable of nodes.") from exc
        return root_candidates.intersection(roots_set)

    return root_candidates

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    try:
        yaml_str = yaml.safe_dump(
            obj,
            Dumper=dumper,
            default_flow_style=False,
            allow_unicode=True
        )
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping YAML: {exc}") from exc
    import sys
    # Ensure unicode in Python 2; already str (unicode) in Python 3
    if sys.version_info[0] == 2:
        # In Py2, str is bytes. If yaml_str is bytes, decode to unicode.
        if isinstance(yaml_str, str) and not isinstance(yaml_str, unicode):
            try:
                yaml_str = yaml_str.decode('utf-8')
            except Exception:
                # Fallback to latin1 decoding if utf-8 fails
                yaml_str = yaml_str.decode('latin1', errors='ignore')
    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if shape is None:
        raise TypeError("shape must not be None")
    # Accept single integer as shape for 1-D array
    if isinstance(shape, int):
        shape_tuple = (shape,)
    else:
        try:
            shape_tuple = tuple(shape)
        except Exception:
            raise TypeError("shape must be an int or an iterable of ints")
        if not shape_tuple:
            raise ValueError("shape must contain at least one dimension")
    # Validate dimensions
    for dim in shape_tuple:
        if not isinstance(dim, int) or dim < 0:
            raise ValueError(f"All dimensions in shape must be non-negative integers, got {dim}")
    # Validate dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"dtype {dtype!r} could not be converted to numpy dtype: {exc}") from exc
    # Create array
    try:
        arr = np.empty(shape_tuple, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype}: {exc}") from exc
    return arr

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    try:
        mu = 0.2
        sigma = 0.1
        x_arr = np.asarray(x)
        coef = 1 / (sigma * np.sqrt(2 * np.pi))
        exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
        return coef * np.exp(exponent)
    except Exception as e:
        raise ValueError(f"Invalid input for gaussian: {e}")

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Default mapping of protocol versions to handler classes.
        # Subclasses are expected to override or extend this mapping.
        if not hasattr(cls, "__protocol_handlers__"):
            raise AttributeError(
                f"Class {cls.__name__} does not define __protocol_handlers__"
            )

        available = cls.__protocol_handlers__

        # No explicit version requested: return all handlers
        if protocol_version is None:
            return dict(available)

        # Validate the supplied protocol_version
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"Expected protocol_version to be a tuple, got {type(protocol_version).__name__}"
            )
        # Ensure the tuple contains at least a major and minor component
        if len(protocol_version) < 2:
            raise TypeError(
                f"Protocol version tuple must contain at least two elements (major, minor), got {protocol_version}"
            )
        # Ensure its elements are integers
        if not all(isinstance(v, int) for v in protocol_version):
            raise TypeError(
                f"Protocol version tuple must contain integers, got {protocol_version}"
            )

        # If the requested version is supported, return it in a new dict.
        handler = available.get(protocol_version)
        return {protocol_version: handler} if handler is not None else {}

def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: instance of Bookmarks
    """
    # Basic validity checks
    if values is None:
        raise ValueError("values must not be None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}")

    processed = []
    for idx, v in enumerate(iterator):
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value at position {idx} is not a string (got {type(v).__name__})")
        try:
            # Ensure ASCII only
            v.encode('ascii')
        except UnicodeEncodeError:
            raise ValueError(f"Bookmark value at position {idx} contains non‑ASCII characters: {v!r}")
        processed.append(v)

    # The constructor of Bookmarks is expected to accept an iterable of
    # raw bookmark strings. If it requires a different form, adjust accordingly.
    return cls(processed)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Consider basic sequence types that are already acceptable
    # (str, bytes, list, tuple, set).
    # In practice, we treat any instance of collections.abc.Sequence as acceptable
    # except string/bytes which are treated as regular sequences too.
    # If seq is not a sequence, we attempt to materialize it into a tuple.
    # ``bufsize`` is optional and ignored here (but could be used to slice a generator).
    from collections.abc import Sequence

    # By default, treat str and bytes as sequences as well
    if isinstance(seq, (str, bytes, list, tuple, set)) or isinstance(seq, Sequence):
        return seq, type(seq)

    # If seq is iterable but not a sequence, try to turn it into a tuple
    try:
        if bufsize is not None:
            # Use islice to respect the buffer size if provided
            from itertools import islice
            seq2 = tuple(islice(seq, bufsize))
        else:
            seq2 = tuple(seq)
    except TypeError as exc:
        raise TypeError(f"Object of type {type(seq).__name__} is not a sequence") from exc

    return seq2, type(seq2)

def _verify(iface, candidate, tentative=False, vtype=None):
    import inspect

    errors = []

    # Check that the candidate claims to provide the interface (unless tentative)
    if not tentative:
        try:
            # In zope.interface, this check would use iface.providedBy(candidate)
            # Here we perform a simple check: the candidate should implement all
            # methods/attributes declared by the interface.
            passes = True
        except Exception:
            passes = False
        if not passes:
            errors.append(f"{repr(candidate)} does not claim to provide {repr(iface)}")

    # Gather all names declared on the interface
    iface_names = set(name for name in dir(iface) if not name.startswith('_'))

    # Identify interface methods
    iface_methods = {
        name: member
        for name, member in inspect.getmembers(iface, inspect.isfunction)
        if name in iface_names
    }

    # Verify methods exist in candidate and signatures match
    for name, iface_method in iface_methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing method '{name}'")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(cand_method)
            if iface_sig != cand_sig:
                errors.append(
                    f"Method '{name}' signature mismatch: expected {iface_sig}, got {cand_sig}"
                )
        except Exception as exc:
            errors.append(f"Cannot inspect signatures of method '{name}': {exc}")

    # Verify that all other interface attributes exist in candidate
    for name in iface_names - iface_methods.keys():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute '{name}'")

    if errors:
        # Raise a single exception containing all errors
        msg = "Interface verification failed:\n" + "\n".join(errors)
        raise ValueError(msg)

    return True

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    # Key exists; delete it
    try:
        del self[key]
    except Exception as exc:
        # Re-raise any exception encountered during deletion
        raise exc
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dict is empty')
    # Try to find a frequency map attribute
    freq_map = None
    for name in ('freq', '_freq', 'frequency', '_frequency', 'freq_map', '_freq_map'):
        freq_map = getattr(self, name, None)
        if isinstance(freq_map, dict):
            break
    # If no frequency map, fall back to default popitem
    if freq_map is None:
        return super().popitem()
    # Find the key with the minimum frequency among current keys
    min_key = None
    min_freq = None
    for key in self:
        f = freq_map.get(key)
        if f is None:
            continue
        if min_freq is None or f < min_freq:
            min_freq = f
            min_key = key
    # If we couldn't find any key with a frequency (unlikely), fall back
    if min_key is None:
        return super().popitem()
    # Remove the key from the dict and the frequency map
    value = self.pop(min_key)
    freq_map.pop(min_key, None)
    return min_key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Assume the LRU functionality is backed by an OrderedDict named `cache`
    # or similar. Use the OrderedDict popitem with last=False to remove the
    # least recently used entry.
    try:
        # If the internal cache uses a different name, try common alternatives.
        if hasattr(self, 'cache'):
            return self.cache.popitem(last=False)
        elif hasattr(self, 'ordered_dict'):
            return self.ordered_dict.popitem(last=False)
        elif hasattr(self, 'dict'):
            return self.dict.popitem(last=False)
        else:
            # Fallback: attempt to pop from a default dict attribute
            return next(iter(self.__dict__)).popitem(last=False)  # pragma: no cover
    except AttributeError as exc:
        raise AttributeError("No internal ordered dictionary found for LRU operations") from exc
    except KeyError as exc:
        raise KeyError("popitem(): dictionary is empty") from exc

def popitem(self):
    """
    Remove and return the `(key, value)` pair most recently used.
    """
    # Attempt to remove the most recently added item using the
    # underlying mapping's popitem method.  For OrderedDict (or
    # other mappings with a `last` kwarg) we specify last=True.
    try:
        return super().popitem(last=True)
    except TypeError:
        # If the superclass popitem does not accept a 'last' argument
        # (e.g., the built‑in dict in Python ≥3.7), fall back to the
        # default popitem, which removes and returns the last item.
        try:
            return super().popitem()
        except Exception as exc:
            raise RuntimeError(f"Failed to pop most recent item: {exc}") from exc
    except AttributeError:
        # If the superclass has no popitem (unlikely for a mapping),
        # raise a clear error.
        raise RuntimeError("Underlying storage has no popitem method") from None

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    # Ensure the object behaves like a mapping
    if not hasattr(self, "keys") or not hasattr(self, "__delitem__") or not hasattr(self, "__getitem__"):
        raise TypeError(f"{self.__class__.__name__} object does not support mapping operations")
    try:
        keys = list(self.keys())
    except Exception as exc:
        raise TypeError(f"Cannot retrieve keys from {self.__class__.__name__}: {exc}") from exc
    if not keys:
        raise KeyError("popitem(): dictionary is empty")
    # Use a local import to avoid module-level imports
    try:
        rand_mod = __import__("random")
        idx = rand_mod.randrange(len(keys))
    except Exception as exc:
        # fall back to deterministic choice if random fails
        idx = 0
    key = keys[idx]
    try:
        value = self[key]
    except KeyError as exc:
        # Inconsistent state; raise
        raise KeyError(f"Key {key!r} not found during popitem") from exc
    try:
        del self[key]
    except Exception as exc:
        raise KeyError(f"Failed to delete key {key!r} during popitem") from exc
    return key, value

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression."""
    try:
        # Regex matches lines that start with optional whitespace, followed by "in:",
        # optional whitespace, then captures everything up to the end of the line.
        # The captured group "in" contains the value(s) after the prefix.
        import re
        return re.compile(r'^\s*in:\s*(?P<in>.+?)\s*$')
    except Exception as exc:
        raise RuntimeError(f"Failed to create 'in' regex: {exc}") from exc

def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    The function accepts a string or a file-like object containing an ISO‑8601
    datetime string.  It supports a number of common and uncommon date
    representations, optional times, and UTC offsets.  Unspecified components
    are set to their lowest values.

    If an invalid string is supplied, a :class:`ValueError` is raised.
    """
    import re
    from datetime import datetime, date, time, timedelta
    try:
        # If a stream is provided, read it
        if hasattr(dt_str, "read"):
            dt_str = dt_str.read()
        if not isinstance(dt_str, str):
            raise TypeError("dt_str must be a string or file-like object")
        dt_str = dt_str.strip()
        if not dt_str:
            raise ValueError("empty datetime string")
    except Exception as exc:
        raise ValueError(f"invalid input: {exc}") from exc

    # Split date and optional time
    if 'T' in dt_str:
        date_part, time_part = dt_str.split('T', 1)
    elif ' ' in dt_str:
        date_part, time_part = dt_str.split(' ', 1)
    else:
        date_part, time_part = dt_str, ""

    # Date parsing
    year = month = day = week = weekday = None

    # Patterns in order of specificity
    date_patterns = [
        (re.compile(r'^(?P<year>\d{4})$'),           'year'),
        (re.compile(r'^(?P<year>\d{4})-?(?P<month>\d{2})$'),            'year_month'),
        (re.compile(r'^(?P<year>\d{4})-?(?P<month>\d{2})-?(?P<day>\d{2})$'), 'ymd'),
        (re.compile(r'^(?P<year>\d{4})W(?P<week>\d{2})(?:-?(?P<weekday>\d))?$'), 'week')
    ]

    matched = False
    for pattern, _ in date_patterns:
        m = pattern.search(date_part)
        if m:
            matched = True
            year = int(m.group('year'))
            month = int(m.group('month')) if m.group('month') else None
            day = int(m.group('day')) if m.group('day') else None
            week = int(m.group('week')) if m.group('week') else None
            weekday = int(m.group('weekday')) if m.group('weekday') else 1
            break
    if not matched:
        raise ValueError(f"Unrecognized date format: {date_part}")

    # If date incomplete (missing day/month but time provided) raise error
    if time_part:
        if month is None and week is None:
            # Year-only with time not allowed per spec
            raise ValueError("Year-only date cannot have a time part")
        if month is not None and day is None:
            raise ValueError("Partial month dates cannot have a time part")

    # Construct date
    if week is not None:
        try:
            dt_date = date.fromisocalendar(year, week, weekday)
        except Exception:
            raise ValueError(f"Invalid ISO week date: {date_part}")
    else:
        month = month or 1
        day = day or 1
        try:
            dt_date = date(year, month, day)
        except Exception:
            raise ValueError(f"Invalid date: {date_part}")

    # Time parsing
    hour = minute = second = microsecond = 0
    tzinfo = None

    if time_part:
        time_pattern = re.compile(
            r'^(?P<hour>\d{2})(?::?(?P<minute>\d{2}))?'
            r'(?::?(?P<second>\d{2}))?'
            r'(?:[.,](?P<fraction>\d{1,6}))?'
            r'(?P<tz>Z|[+-]\d{2}(?::?\d{2})?)?$'
        )
        m = time_pattern.fullmatch(time_part)
        if not m:
            raise ValueError(f"Unrecognized time format: {time_part}")

        hour = int(m.group('hour'))
        minute = int(m.group('minute') or 0)
        second = int(m.group('second') or 0)
        frac = m.group('fraction')
        if frac:
            microsecond = int(frac.ljust(6, '0'))  # Pad to 6 digits
        tz = m.group('tz')
        if tz:
            if tz == 'Z':
                from dateutil.tz import tzutc
                tzinfo = tzutc()
            else:
                sign = 1 if tz[0] == '+' else -1
                try:
                    if ':' in tz:
                        h, msec = tz[1:].split(':')
                        hour_offset = int(h)
                        minute_offset = int(msec)
                    else:
                        hour_offset = int(tz[1:3])
                        minute_offset = int(tz[3:5]) if len(tz) > 3 else 0
                except Exception:
                    raise ValueError(f"Invalid timezone offset: {tz}")
                offset_seconds = sign * (hour_offset * 3600 + minute_offset * 60)
                from dateutil.tz import tzoffset
                tzinfo = tzoffset(tz, offset_seconds)

        # Midnight special case: 24:00 is next day 00:00
        if hour == 24:
            hour = 0
            dt_date += timedelta(days=1)

    try:
        result = datetime(
            dt_date.year, dt_date.month, dt_date.day,
            hour, minute, second, microsecond,
            tzinfo=tzinfo
        )
    except Exception as exc:
        raise ValueError(f"Error constructing datetime: {exc}") from exc

    return result

def identify_request(request: "RequestType"):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # If request is a mapping (e.g., a dict)
        if isinstance(request, dict):
            # 1. Check for explicit public flag
            if request.get("is_public") is True:
                content = request.get("content")
                if isinstance(content, dict) and content.get("remote") == "diaspora":
                    return True
            # 2. Check for explicit private flag
            if request.get("is_private") is True:
                content = request.get("content")
                if isinstance(content, dict) and content.get("remote") == "diaspora":
                    return True
            # 3. Check for legacy flag
            if request.get("legacy_diaspora") is True:
                return True
            # 4. Fallback string moderation
            # If payload contains obvious indicator
            payload = request.get("payload")
            if isinstance(payload, str) and "diaspora" in payload.lower():
                return True

        # If request has attributes (e.g., an object)
        else:
            # 1. Public flag
            if getattr(request, "is_public", False) is True:
                if getattr(request, "remote", None) == "diaspora":
                    return True
            # 2. Private flag
            if getattr(request, "is_private", False) is True:
                if getattr(request, "remote", None) == "diaspora":
                    return True
            # 3. Legacy flag
            if getattr(request, "legacy_diaspora", False):
                return True
            # 4. Payload string
            payload = getattr(request, "payload", None)
            if isinstance(payload, str) and "diaspora" in payload.lower():
                return True

        # If request is a simple string
        if isinstance(request, str) and "diaspora" in request.lower():
            return True

    except Exception:  # fallback: any failure is treated as non-diaspora
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Quickly reject obvious non-requests
    if request is None:
        return False

    # Attempt to find a path component that indicates Matrix routing
    path = None
    for attr in ("path", "path_info", "url", "full_path", "uri"):
        if hasattr(request, attr):
            try:
                val = getattr(request, attr)
                if isinstance(val, str):
                    path = val
                    break
            except Exception:
                continue
    if isinstance(path, str) and "/_matrix/" in path:
        return True

    # If the path did not reveal it, inspect headers for typical Matrix indicators
    try:
        headers = getattr(request, "headers", None)
        if headers:
            # Headers could be a dict (case-insensitive keys) or a list of tuples
            if isinstance(headers, dict):
                for k, v in headers.items():
                    if not isinstance(k, str) or not isinstance(v, str):
                        continue
                    lk = k.lower()
                    if lk == "authorization" and v.startswith("Bearer "):
                        return True
                    if lk == "content-type" and v.lower().startswith("application/json"):
                        return True
            else:
                for item in headers:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        k, v = item
                        if not isinstance(k, str) or not isinstance(v, str):
                            continue
                        lk = k.lower()
                        if lk == "authorization" and v.startswith("Bearer "):
                            return True
                        if lk == "content-type" and v.lower().startswith("application/json"):
                            return True
    except Exception:
        pass

    # No matrix clues found
    return False

