def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        if not url or not isinstance(url, str):
            return None
        if not url.lower().startswith(("http://", "https://")):
            url = "http://" + url
        # Subclass Request to force HEAD method
        class HeadRequest(urllib.request.Request):
            def get_method(self):
                return "HEAD"
        req = HeadRequest(url)
        with urllib.request.urlopen(req, timeout=10) as resp:
            # getheader returns None if header not present
            return resp.getheader("Content-Type")
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.

    A valid tag satisfies the following conditions:
    1. It is a non‑empty string with length between 1 and 30 characters inclusive.
    2. It contains only lowercase ASCII letters, digits and hyphens.
    3. It starts and ends with an alphanumeric character (no leading or trailing hyphen).
    4. Consecutive hyphens are not allowed.
    5. It must contain at least one letter (so purely numeric tags are rejected).

    The function is tolerant of incorrect input types and returns False in those cases instead of raising an exception.
    """
    # Ensure the input is a string
    if not isinstance(tag, str):
        return False

    # Empty string or length constraints
    if not (1 <= len(tag) <= 30):
        return False

    # No whitespace allowed anywhere
    if any(c.isspace() for c in tag):
        return False

    # Start and end must be alphanumeric
    if not (tag[0].isalnum() and tag[-1].isalnum()):
        return False

    # No consecutive hyphens
    if '--' in tag:
        return False

    has_letter = False
    for c in tag:
        if c.isalpha():
            # Must be lowercase letters
            if not c.islower():
                return False
            has_letter = True
        elif c.isdigit():
            continue
        elif c == '-':
            continue
        else:
            # Any other character is invalid
            return False

    if not has_letter:
        return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = iter(node)
    except TypeError:
        raise TypeError("Provided node is not an iterable XML element")
    result = {}
    for child in children:
        # Skip objects that don't look like XML elements
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic input validation
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Prepare base URL (remove any trailing slash)
    base = url.rstrip("/")

    # Default NodeInfo path if none provided
    if document_path is None:
        doc_path = "/nodeinfo/2.0"
    else:
        # Ensure leading slash and strip any surrounding whitespace
        doc_path = document_path.strip()
        if not doc_path.startswith("/"):
            doc_path = "/" + doc_path

    # Construct href
    href = base + doc_path

    # Build the well‑known document
    return {
        "@context": "https://www.w3.org/ns/json-ld#",
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result: Dict = {}
    if not document or not isinstance(document, str):
        return result

    # Try JSON first
    try:
        data = json.loads(document)
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('aliases', [])
        result['properties'] = data.get('properties', {})
        # Ensure list of links, drop unknown keys
        links = data.get('links', [])
        if isinstance(links, list):
            result['links'] = links
        else:
            result['links'] = []
        return result
    except Exception:
        pass

    # Fallback to XML (XRD)
    try:
        ET = xml.etree.ElementTree
        root = ET.fromstring(document)
    except Exception:
        return result

    namespace = ''
    if root.tag.startswith("{"):
        namespace = root.tag.split("}")[0] + "}"
    ns = {"ns": namespace} if namespace else {}

    def _get_text(path):
        elem = root.find(path, ns)
        return elem.text.strip() if elem is not None and elem.text else None

    result['subject'] = _get_text("ns:Subject" if namespace else "Subject")

    aliases = root.findall("ns:Alias" if namespace else "Alias", ns)
    result['aliases'] = [a.text.strip() for a in aliases if a.text]

    props = {}
    for prop in root.findall("ns:Property" if namespace else "Property", ns):
        t = prop.attrib.get("type")
        if t and prop.text:
            props[t] = prop.text.strip()
    result['properties'] = props

    links = []
    for ln in root.findall("ns:Link" if namespace else "Link", ns):
        link_dict: Dict[str, str] = {}
        for attr in ("rel", "type", "href"):
            val = ln.attrib.get(attr)
            if val:
                link_dict[attr] = val
        if link_dict:
            links.append(link_dict)
    result['links'] = links

    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    # Validate handle format: should contain '@'
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string in the form 'user@host'")

    # Split into user and host; ignore any additional @ outside the first
    user, host = handle.split('@', 1)

    # Construct the webfinger URL
    resource = f"acct:{handle}"
    encoded_resource = urllib.parse.quote(resource, safe='')
    url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                # Non-OK status: return empty dict
                return {}
            content_type = response.headers.get('Content-Type', '')
            if not content_type.startswith('application/json'):
                # Unexpected content type; try to parse anyway
                data = response.read().decode('utf-8')
                try:
                    return json.loads(data)
                except json.JSONDecodeError:
                    return {}
            # Parse JSON content
            try:
                return json.load(response)
            except json.JSONDecodeError:
                return {}
    except Exception:
        # Any network or parsing error results in an empty dict
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic validation
    if not isinstance(url, str) or not url.strip():
        return (None, ValueError("A non-empty URL string must be provided."))

    # Normalise method name
    method_name = method.lower() if isinstance(method, str) else ""
    allowed_methods = {"get", "post", "put", "patch", "delete", "head", "options", "trace"}
    if method_name not in allowed_methods:
        return (None, ValueError(f"Unsupported HTTP method: {method}"))

    # Attempt to send the request and capture any exception
    try:
        # We allow the caller to pass in any extra positional or keyword arguments
        # that requests.request() might accept (like files, headers, auth, etc.)
        response = requests.request(method=method_name, url=url, data=data,
                                    timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names found within the directories specified in *settings_dirs*,
    optionally filtering by *spec_option*.

    Parameters
    ----------
    settings_dirs : iterable
        An iterable of path-like objects or strings representing directories to search.

    spec_option : str or iterable of str, optional
        If a string, may be a glob pattern (e.g. '*.ini') or a simple suffix (e.g. 'ini').
        If an iterable, each element is treated as a separate pattern.
        If None or empty, all regular files in the directories are returned.

    Returns
    -------
    list of str
        File names (base names, not full paths) that match the filtering criteria.

    Notes
    -----
    * Directories that do not exist or are not readable are skipped silently.
    * The function does not follow symbolic links to directories.
    * Duplicate file names from different directories are included as separate entries.
    * Errors caused by invalid patterns or permission issues are ignored; the function always
      returns a list, even if it is empty.

    Examples
    --------
    >>> list_of_file_names(['/etc', '/usr/lib'], '*.conf')
    ['asmt.conf', 'httpd.conf', ...]
    >>> list_of_file_names(['/tmp'], 'txt')
    ['example.txt']
    """
    # Import within the function to avoid global import statements
    import pathlib
    results = []

    # Ensure settings_dirs is iterable (but not a string)
    try:
        iterator = iter(settings_dirs)
    except TypeError:
        raise TypeError("settings_dirs must be an iterable of path-like objects or strings")

    # Normalize spec_option into a list of patterns
    if spec_option is None or spec_option == "":
        patterns = [""]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        # Treat any non-string iterable as a list of patterns
        try:
            patterns = list(spec_option)
        except TypeError:
            raise TypeError("spec_option must be a string, None, empty, or an iterable of strings")

    # Helper to determine whether a pattern should be treated as a suffix
    def _normalize_pattern(pat):
        if not pat:
            return pat
        # If the pattern already contains glob wildcards, keep it as is
        if any(ch in pat for ch in "*?[]"):
            return pat
        # Strip leading dot if present
        suffix = pat.lstrip('.')
        if not suffix:
            return ""  # Any file if pattern is just '.'
        return f"*.{suffix}"

    normalized_patterns = [_normalize_pattern(pat) for pat in patterns]

    for dir_path in iterator:
        if dir_path is None:
            continue
        try:
            p = pathlib.Path(dir_path)
        except Exception:
            continue  # Skip invalid path-like objects
        if not p.is_dir():
            continue  # Skip non-directories

        # If pattern is empty strings, list all files
        if all(not pat for pat in normalized_patterns):
            for file in p.iterdir():
                try:
                    if file.is_file():
                        results.append(file.name)
                except Exception:
                    continue  # Skip unreadable entries
            continue

        # Process each pattern separately
        for pat in normalized_patterns:
            if not pat:
                continue
            try:
                for file in p.glob(pat):
                    try:
                        if file.is_file():
                            results.append(file.name)
                    except Exception:
                        continue
            except Exception:
                # If globbing fails for a pattern, ignore it
                continue

    return results

def ansible_config_manager(cls):
    """Gets the ansible config manager."""
