def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Ensure we have some content to work with
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # If we received a dictionary straight away, use it
    if isinstance(spec_content, dict):
        spec_dict = spec_content
    else:
        # We expect either a str or bytes containing YAML
        if isinstance(spec_content, bytes):
            try:
                spec_content = spec_content.decode('utf-8')
            except Exception as e:
                raise IRValidatorException(f"Unable to decode spec content: {e}")

        if not isinstance(spec_content, str):
            raise IRValidatorException(f"Spec content must be a string or dictionary, got {type(spec_content).__name__}")

        try:
            # yaml module is assumed to be imported at module level
            spec_dict = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML: {e}")

    # yaml.safe_load may return None for empty documents
    if spec_dict is None:
        raise IRValidatorException("Spec content is empty or not a valid YAML document")

    if not isinstance(spec_dict, dict):
        raise IRValidatorException(f"Spec content must parse to a mapping, got {type(spec_dict).__name__}")

    # Define the minimal set of required fields.  Adjust this list
    # if your spec has additional mandatory properties.
    required_fields = ["name", "spec_version"]

    missing = [field for field in required_fields if field not in spec_dict]
    if missing:
        raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")

    return spec_dict

def validate_from_file(cls, yaml_file=None):
        """
        Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file: {exc}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a dictionary at its root")

        # Determine required fields if defined on the class
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields is not None:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(f"Missing required field(s): {', '.join(missing)}")

        # Simple sanity check for empty dictionary
        if not data:
            raise IRValidatorException("YAML file is empty or contains no valid keys")

        return data

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Returns a dictionary of default values for arguments.
    """
    defaults = {}
    try:
        # Retrieve spec from the instance, if it exists
        spec = getattr(self, "spec", None)
        if spec is None:
            return defaults
        if not isinstance(spec, dict):
            raise TypeError("spec attribute must be a dictionary")

        # If spec contains a top‑level 'defaults' key, merge it first
        top_defaults = spec.get("defaults")
        if isinstance(top_defaults, dict):
            defaults.update(top_defaults)

        # Scan the remaining entries for per‑argument defaults
        for key, value in spec.items():
            if key == "defaults":
                continue
            # If the entry is a dictionary that contains a 'default' key
            if isinstance(value, dict) and "default" in value:
                defaults[key] = value["default"]
            # If the entry itself is a tuple or list with the first element as the default
            elif isinstance(value, (tuple, list)) and value:
                defaults[key] = value[0]
            # If the entry is a simple value, treat it as a default
            elif not isinstance(value, dict) and not isinstance(value, (tuple, list)):
                defaults[key] = value

        # Merge any additional defaults supplied through a dedicated attribute
        other_defaults = getattr(self, "other_defaults", None)
        if isinstance(other_defaults, dict):
            defaults.update(other_defaults)

    except Exception:
        # In case of any failure return an empty mapping to avoid breaking the caller
        return {}
    return defaults

def get_deprecated_args(self):
        """Returning dict with options which deprecate others."""
        try:
            deprecated = getattr(self, "_deprecated_args", None)
            if isinstance(deprecated, dict) and deprecated is not None:
                # Return a shallow copy to prevent accidental modification of the original dict
                return dict(deprecated)
        except Exception:
            pass
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure inputs are dictionaries; fall back to empty dicts if not provided
    if not isinstance(cli_args, dict):
        try:
            cli_args = dict(cli_args or {})
        except Exception:
            cli_args = {}
    if not isinstance(answer_file_args, dict):
        try:
            answer_file_args = dict(answer_file_args or {})
        except Exception:
            answer_file_args = {}

    # Deprecated arguments mapping; subclasses may define their own mapping
    # Format: {'old_arg_name': 'new_arg_name', ...}
    deprecated_map = getattr(self, 'deprecated_args', {})

    # Helper function to output warnings
    def _warn(source, key):
        new_key = deprecated_map.get(key, None)
        if new_key:
            print(f"[Deprecation Warning] Argument '{key}' from {source} is deprecated. "
                  f"Please use '{new_key}' instead.")
        else:
            # If no new mapping provided, still warn about deprecation
            print(f"[Deprecation Warning] Argument '{key}' from {source} is deprecated "
                  f"and has no replacement defined.")

    # Check CLI arguments
    for key in cli_args:
        if key in deprecated_map:
            _warn('CLI', key)

    # Check answer file arguments
    for key in answer_file_args:
        if key in deprecated_map:
            _warn('Answer file', key)

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    The method attempts to resolve the full list of option specifications for a
    given command name.  It supports several internal storage layouts that
    other parts of the application might expose:

        * ``self.command_options`` – a mapping
          ``command_name -> list_of_options``.
        * ``self.parsers`` – a mapping of parser instances whose
          attributes are inspected for ``command_name`` and ``option_specs``.

    A ``TypeError`` is raised when *command_name* is not a non-empty string.
    If the command is not found the function returns an empty list rather than
    raising an exception; callers can decide how to handle the empty result.

    Parameters
    ----------
    command_name : str
        Name of the command whose options should be returned (e.g. "main",
        "virsh", "ospd", ...).

    Returns
    -------
    list
        A list of option specifications for the requested command.
    """
    if not isinstance(command_name, str) or not command_name:
        raise TypeError("command_name must be a non-empty string")

    # 1. Try direct command_options dictionary
    cmd_opts = getattr(self, "command_options", None)
    if isinstance(cmd_opts, dict) and command_name in cmd_opts:
        try:
            return list(cmd_opts[command_name])
        except Exception:
            # Unexpected value type; fall through
            pass

    # 2. Search through parser instances (if present)
    parsers = getattr(self, "parsers", None)
    if isinstance(parsers, dict):
        for parser in parsers.values():
            try:
                # Some parsers may expose the name via a property
                if getattr(parser, "command_name", None) == command_name:
                    # Prefer a direct option_specs attribute
                    opts = getattr(parser, "option_specs", None)
                    if isinstance(opts, (list, tuple)):
                        return list(opts)
                    # Fallback to a method if available
                    if callable(getattr(parser, "get_option_specs", None)):
                        return list(parser.get_option_specs())
            except Exception:
                continue  # Ignore misbehaving parser and keep searching

    # 3. Last-resort: try to resolve a parser attribute with the command name
    parser_attr = getattr(self, command_name, None)
    if parser_attr and hasattr(parser_attr, "option_specs"):
        return list(parser_attr.option_specs)

    # 4. Command not found: return an empty list for graceful handling
    return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Retrieve the set of required argument names from the instance.
    try:
        required = set(self.required_args)
    except AttributeError:
        raise AttributeError(
            "The instance does not define 'required_args', "
            "so it cannot check for missing arguments."
        )
    except Exception as exc:
        raise AssertionError(f"Unable to retrieve required arguments: {exc}")

    # Determine the set of provided argument names.
    provided = set()
    if args is None:
        pass  # empty set of provided args
    elif isinstance(args, dict):
        provided = set(args.keys())
    else:
        # Assume an iterable of names; guard against strings/binary.
        if isinstance(args, (str, bytes)):
            raise TypeError("args cannot be a string or bytes object; use a dict or iterable of names")
        try:
            for item in args:
                provided.add(str(item))
        except TypeError:
            raise TypeError("args must be a dict or an iterable of argument names")

    # Identify missing required arguments.
    missing = required - provided
    if missing:
        missing_list = ", ".join(sorted(missing))
        raise ValueError(f"Missing required arguments: {missing_list}")

    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    Parameters
    ----------
    args
        The received arguments, expected to be a dict or a sequence.

    Raises
    ------
    TypeError
        If the provided ``args`` is not a mapping or a sequence.
    ValueError
        If an argument exceeds the allowed maximum length.

    Notes
    -----
    This method expects the instance to define an attribute ``max_lengths`` that
    contains the allowed lengths for each argument. ``max_lengths`` may be a
    mapping (matching a dict ``args``) or a sequence (matching a list/tuple
    ``args``). If no such attribute exists or the type is incompatible, the
    method silently returns.
    """
    # Require args to be a mapping or a sequence
    if args is None or not (isinstance(args, dict) or isinstance(args, (list, tuple))):
        raise TypeError("args must be a dict or a sequence")
    # Retrieve the configured maximum lengths
    max_lengths = getattr(self, "max_lengths", None)
    if max_lengths is None:
        return
    # Handle mapping case
    if isinstance(args, dict) and isinstance(max_lengths, dict):
        for key, value in args.items():
            if key not in max_lengths:
                continue
            max_len = max_lengths[key]
            if max_len is None:
                continue
            try:
                val_len = len(value)
            except Exception:
                # value has no length; skip the check
                continue
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{key}' length {val_len} exceeds maximum allowed {max_len}"
                )
    # Handle sequence case
    elif isinstance(args, (list, tuple)) and isinstance(max_lengths, (list, tuple)):
        for idx, value in enumerate(args):
            if idx >= len(max_lengths):
                continue
            max_len = max_lengths[idx]
            if max_len is None:
                continue
            try:
                val_len = len(value)
            except Exception:
                continue
            if val_len > max_len:
                raise ValueError(
                    f"Argument at index {idx} length {val_len} exceeds maximum allowed {max_len}"
                )
    # If types don't match, do nothing
    return

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. It can be an iterable of values (e.g.
                 list, tuple, set) or a mapping (dict). Each value is compared
                 against ``self.min_value`` and ``self.max_value``.  If the
                 value is outside the range a ``ValueError`` is raised.  If
                 ``self`` does not define ``min_value`` or ``max_value``,
                 ``AttributeError`` will be raised.  If the provided value
                 cannot be compared with the thresholds a ``TypeError`` is
                 raised.

    :raises ValueError: if any argument is outside the inclusive
                        [min_value, max_value] range.
    :raises TypeError: if ``args`` is not iterable or if an argument
                       cannot be compared with the thresholds.
    """
    # Ensure min/max are available
    try:
        min_val = self.min_value
        max_val = self.max_value
    except AttributeError:
        raise AttributeError("Object must have 'min_value' and 'max_value' attributes")

    if None in (min_val, max_val):
        raise ValueError("min_value and max_value must not be None")

    if min_val > max_val:
        raise ValueError("min_value must be less than or equal to max_value")

    if args is None:
        return

    # Prepare iterable
    if isinstance(args, dict):
        iterable = args.values()
    else:
        try:
            iterable = iter(args)
        except TypeError:
            raise TypeError("args must be an iterable or a mapping")

    for val in iterable:
        try:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument value {val!r} is outside the "
                    f"allowed range [{min_val}, {max_val}]"
                )
        except TypeError as exc:
            raise TypeError(
                f"Cannot compare argument {val!r} with min/max values: {exc}"
            ) from exc

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated ``vars_dict`` (in place modification)
    """
    if vars_dict is None or not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    # If a dictionary is supplied, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Otherwise, expect an iterable of strings or dicts
    try:
        iterator = iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be None, a dict, or an iterable")

    for item in iterator:
        # Direct dict updates
        if isinstance(item, dict):
            vars_dict.update(item)
            continue

        # Only parse string items
        if not isinstance(item, str):
            continue

        # Split on first '=' or ':' if present
        if "=" in item:
            key, val = item.split("=", 1)
        elif ":" in item:
            key, val = item.split(":", 1)
        else:
            key, val = item, ""

        key = key.strip()
        if not key:
            continue
        val = val.strip()

        # Try to interpret the value as JSON (handles numbers, booleans, lists, etc.)
        try:
            import json
            parsed_val = json.loads(val)
            vars_dict[key] = parsed_val
        except Exception:
            # Fallback: keep as plain string
            vars_dict[key] = val

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified dict with coerced values.
    """
    if not isinstance(values_dict, dict):
        # nothing to do if not a dict
        return values_dict

    # Helper functions to detect types
    def _is_int(val):
        try:
            int(val)
            # disallow floats that look like ints
            return True
        except Exception:
            return False

    def _is_float(val):
        try:
            float(val)
            return True
        except Exception:
            return False

    def _is_bool(val):
        return val.lower() in ("true", "false", "yes", "no", "1", "0")

    def _to_bool(val):
        if val.lower() in ("true", "yes", "1"):
            return True
        return False

    for key, value in list(values_dict.items()):
        # Only handle string-like values
        if not isinstance(value, str):
            continue
        val = value.strip()
        if val == "":
            continue
        # List detection: comma separated
        if "," in val:
            # Split and strip each element
            lst = [elem.strip() for elem in val.split(",") if elem.strip() != ""]
            values_dict[key] = lst
            continue
        # Boolean detection
        if _is_bool(val):
            values_dict[key] = _to_bool(val)
            continue
        # Integer detection
        if _is_int(val):
            try:
                values_dict[key] = int(val)
                continue
            except Exception:
                pass
        # Float detection
        if _is_float(val):
            try:
                values_dict[key] = float(val)
                continue
            except Exception:
                pass
        # Leave as string otherwise
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(plugin_dir, (str, bytes)):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Provided plugin_dir {plugin_dir!r} is not a directory")

    # possible spec file names
    spec_filenames = [
        "plugin.json",
        "spec.json",
        "plugin.yaml",
        "plugin.yml",
        "spec.yaml",
        "spec.yml",
    ]

    spec_path = None
    for fn in spec_filenames:
        candidate = os.path.join(plugin_dir, fn)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        # No spec file found; return empty dict
        return {}

    ext = os.path.splitext(spec_path)[1].lower()
    try:
        if ext == ".json":
            with open(spec_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            # attempt to load yaml
            try:
                import yaml
            except Exception as exc:
                # yaml not available; cannot parse spec
                raise RuntimeError("YAML parser is required for loading the spec") from exc
            with open(spec_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as e:
        # If any error occurs while reading/parsing, return empty dict
        return {}

    if isinstance(data, dict):
        return _flatten(data)
    else:
        # If top-level spec is not a dict, return empty dict
        return {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    try:
        # Determine a default configuration file path
        try:
            base_dir = os.path.dirname(__file__)
        except NameError:
            base_dir = os.getcwd()
        default_path = os.path.join(base_dir, 'config.yaml')

        # Set environment variables if they are not already defined
        if not os.getenv('CONFIG'):
            os.environ['CONFIG'] = default_path
        if not os.getenv('CONFIG_PATH'):
            os.environ['CONFIG_PATH'] = default_path
    except Exception:
        # In case of any issue, silently ignore and leave the environment unchanged
        pass
